import { createORM } from '@cossackframework/database';
import { nodeSQLite } from '@cossackframework/database/node';

const orm = createORM({ adapter: await nodeSQLite(), entities: [] });
try {
  const notes = orm.sql.id('notes');
  const body = orm.sql.id('body');
  await orm.sql`CREATE TABLE ${notes} (${body} TEXT NOT NULL)`;
  await orm.sql`INSERT INTO ${notes} (${body}) VALUES (${'hello'})`;

  const hostile = "' OR 1=1 --";
  const result = await orm.sql<{ body: string }>`SELECT ${body} FROM ${notes} WHERE ${body} = ${hostile}`;
  if (result.rows.length !== 0) throw new Error('Query input must remain a bound value');

  const stored = await orm.sql<{ body: string }>`SELECT ${body} FROM ${notes} WHERE ${body} = ${'hello'}`;
  if (stored.rows[0]?.body !== 'hello') throw new Error('The safe value was not stored');
} finally {
  await orm.close();
}

import { createORM } from '@cossackframework/database';
import { d1, type D1DatabaseBinding } from '@cossackframework/database/cloudflare';

export async function findNote(database: D1DatabaseBinding, body: string) {
  const orm = createORM({ adapter: await d1(database), entities: [] });
  try {
    const result = await orm.sql<{ body: string }>`SELECT body FROM notes WHERE body = ${body}`;
    return result.rows[0]?.body;
  } finally {
    await orm.close();
  }
}

import { createORM, defineSeeder, MigrationRunner, SeederRunner, type Migration } from '@cossackframework/database';
import { nodeSQLite } from '@cossackframework/database/node';

const migration = {
  name: '0001_create_guide_notes',
  up({ orm, schema }) {
    schema.raw(orm.sql.fragment`CREATE TABLE guide_notes (id INTEGER PRIMARY KEY, key TEXT NOT NULL UNIQUE, body TEXT NOT NULL)`);
  },
  down({ orm, schema }) {
    schema.raw(orm.sql.fragment`DROP TABLE guide_notes`);
  },
} satisfies Migration;

const orm = createORM({ adapter: await nodeSQLite(), entities: [] });
try {
  const migrations = new MigrationRunner(orm, [migration]);
  const applied = await orm.run(() => migrations.up());
  if (applied[0] !== migration.name) throw new Error('Migration was not applied');

  const status = await orm.run(() => migrations.status());
  if (status[0]?.state !== 'applied') throw new Error('Migration checksum status is not applied');

  const welcome = defineSeeder({
    name: 'welcome-note',
    async run({ sql }) {
      await sql`INSERT INTO guide_notes (key, body) VALUES (${'welcome'}, ${'Hello'}) ON CONFLICT (key) DO UPDATE SET body = excluded.body`;
    },
  });
  const seeders = new SeederRunner(orm, [welcome]);
  await seeders.run();
  await seeders.run();

  const notes = await orm.sql<{ key: string; body: string }>`SELECT key, body FROM guide_notes`;
  if (notes.rows.length !== 1 || notes.rows[0]?.key !== 'welcome') {
    throw new Error('Repeating the seeder must not duplicate its stable key');
  }

  const reverted = await orm.run(() => migrations.down());
  if (reverted[0] !== migration.name) throw new Error('Migration was not reverted');
} finally {
  await orm.close();
}

import { BaseEntity, Column, Entity, MoreThanOrEqual, PrimaryGeneratedColumn, createORM } from '@cossackframework/database';
import { nodeSQLite } from '@cossackframework/database/node';

@Entity()
class Note extends BaseEntity {
  @PrimaryGeneratedColumn()
  declare id: number;

  @Column({ type: 'text' })
  declare title: string;

  @Column({ type: 'integer' })
  declare priority: number;

  @Column({ type: 'boolean' })
  declare published: boolean;
}

const orm = createORM({ adapter: await nodeSQLite(), entities: [Note] });
try {
  const notes = orm.sql.id('notes');
  await orm.sql`CREATE TABLE ${notes} (id INTEGER PRIMARY KEY, title TEXT NOT NULL, priority INTEGER NOT NULL, published INTEGER NOT NULL)`;
  await orm.model(Note).insert([
    { title: 'Draft', priority: 1, published: false },
    { title: 'Query guide', priority: 3, published: true },
    { title: 'Release notes', priority: 2, published: true },
  ]);

  const highPriority = await orm.model(Note).find({
    where: { published: true, priority: MoreThanOrEqual(2) },
    select: ['id', 'title'],
    order: { title: 'asc' },
    take: 2,
  });
  if (highPriority.length !== 2 || highPriority[0]?.title !== 'Query guide') {
    throw new Error('The typed find filter or ordering returned unexpected rows');
  }

  const projection = await orm.model(Note).query('note')
    .select('id', 'title')
    .where(where => where.eq('published', true))
    .orderBy('priority', 'desc')
    .getRawMany();
  if (projection[0]?.title !== 'Query guide' || 'priority' in (projection[0] ?? {})) {
    throw new Error('The typed projection returned unexpected columns');
  }
} finally {
  await orm.close();
}
